const CHECK_ALPHABET = "ACDEFGHJKLMNPQRSTUVWXYZ";
const CODE_RE = /^V(\d{2})-([A-Z]+)-(\d{3})-([A-Z])$/;

/** Row number -> bijective base 26 label (1 -> "A", 26 -> "Z", 27 -> "AA"). */
function rowToLabel(row) {
	let label = "";
	let n = row;
	while (n > 0) {
		n -= 1;
		label = String.fromCharCode(65 + (n % 26)) + label;
		n = Math.floor(n / 26);
	}
	return label;
}

/** Bijective base 26 label -> row number ("A" -> 1, "Z" -> 26, "AA" -> 27). */
function labelToRow(label) {
	let n = 0;
	for (const ch of label) {
		n = n * 26 + (ch.charCodeAt(0) - 64);
	}
	return n;
}

/** Check letter for the text before the last "-". */
function checkLetter(prefix) {
	let sum = 0;
	for (const ch of prefix) {
		sum += ch.charCodeAt(0);
	}
	return CHECK_ALPHABET[sum % 23];
}

/** @param {{ venue: number, row: number, seat: number }} ticket @returns {string} */
export function encodeTicket(ticket) {
	const { venue, row, seat } = ticket;
	if (!Number.isInteger(venue) || venue < 1 || venue > 99) {
		throw new RangeError("venue must be an integer from 1 to 99");
	}
	if (!Number.isInteger(row) || row < 1) {
		throw new RangeError("row must be an integer of 1 or more");
	}
	if (!Number.isInteger(seat) || seat < 1 || seat > 999) {
		throw new RangeError("seat must be an integer from 1 to 999");
	}
	const prefix = `V${String(venue).padStart(2, "0")}-${rowToLabel(row)}-${String(seat).padStart(3, "0")}`;
	return `${prefix}-${checkLetter(prefix)}`;
}

/** @param {string} code @returns {{ venue: number, row: number, seat: number }} */
export function decodeTicket(code) {
	if (typeof code !== "string") {
		throw new SyntaxError("ticket code must be a string");
	}
	const m = CODE_RE.exec(code);
	if (!m) {
		throw new SyntaxError("ticket code must look like V07-AB-012-G");
	}
	const venue = Number(m[1]);
	const seat = Number(m[3]);
	const prefix = `V${m[1]}-${m[2]}-${m[3]}`;
	if (venue === 0 || seat === 0 || m[4] !== checkLetter(prefix)) {
		throw new RangeError("invalid ticket code");
	}
	return { venue, row: labelToRow(m[2]), seat };
}

